+++ b/src/object/coin_explode.cpp
@@ -43,9 +43,9 @@ CoinExplode::update(float )
     { -1.5, -5.5 }, { -1, -6 }, { -0.5, -6.5 }
   };

-  for(const auto& vector: coin_velocities)
+  for (auto& velocity : coin_velocities)
   {
-    auto velocity = vector * (mag - gameRandom.randf(rand));
+    velocity *= mag - gameRandom.randf(rand);
     Sector::get().add<HeavyCoin>(position, velocity, m_count_stats, m_sprite);
   }

=== environment/bugs/bug_02.patch
diff --git a/src/object/coin.cpp b/src/object/coin.cpp
index 8c7db8bea..28585be73 100644
